// @generated by:gauntlet run:scan-robustness
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::Value;
use std::time::Duration;

fn settings() -> ScanOptions {
    let mut settings = ScanOptions {
        samples: 1,
        discover: false,
        paths: vec![],
        ..ScanOptions::default()
    };
    settings.network.no_proxy = true;
    settings
}

fn inspect(server: &Server, options: &ScanOptions, requests: usize) -> Value {
    let mut bounds = limits();
    bounds.max_requests = requests;
    serde_json::to_value(scan_configured(&server.url, bounds, options).unwrap()).unwrap()
}

fn technology<'a>(report: &'a Value, name: &str) -> Option<&'a Value> {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|tech| tech["name"] == name)
}

#[test]
fn an_external_html_base_does_not_turn_relative_assets_into_target_components() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "",
            "<base href='https://cdn.example/'>\
        <script src='wp-content/plugins/example/main.js'></script><a href='info.php'>info</a>",
        )
    });
    let mut options = settings();
    options.discover = true;
    let report = inspect(&server, &options, 8);
    assert!(technology(&report, "WordPress plugin:example").is_none());
    assert!(report["discovered_paths"].as_array().unwrap().is_empty());
    assert_eq!(server.paths.lock().unwrap().as_slice(), ["/"]);
}

#[test]
fn the_first_html_base_controls_relative_diagnostic_routes() {
    let server = Server::new(|path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                "<base href='/app/'><base href='/ignored/'>\
            <a href='info.php'>info</a><script src='wp-content/plugins/example/main.js'></script>",
            )
        } else {
            response("404 Not Found", "", "missing")
        }
    });
    let mut options = settings();
    options.discover = true;
    let report = inspect(&server, &options, 8);
    assert!(technology(&report, "WordPress plugin:example").is_some());
    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/app/info.php"]
    );
}

#[test]
fn absolute_same_origin_references_work_even_with_an_external_base() {
    let address = std::sync::Arc::new(std::sync::Mutex::new(String::new()));
    let seen = address.clone();
    let origin = Server::new(move |path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                &format!(
                    "<base href='https://cdn.example/'>\
            <a href='{}info.php'>info</a>",
                    seen.lock().unwrap()
                ),
            )
        } else {
            response("404 Not Found", "", "missing")
        }
    });
    *address.lock().unwrap() = origin.url.clone();
    let mut options = settings();
    options.discover = true;
    inspect(&origin, &options, 8);
    assert_eq!(origin.paths.lock().unwrap().as_slice(), ["/", "/info.php"]);
}

#[test]
fn inert_or_documentation_error_footers_never_supply_runtime_versions() {
    for body in [
        "<!-- <address>PHP/8.4.26 Apache/2.4.62</address> -->",
        "<div hidden><address>PHP/8.4.26 Apache/2.4.62</address></div>",
        "<template><address>PHP/8.4.26 Apache/2.4.62</address></template>",
        "<pre><address>PHP/8.4.26 Apache/2.4.62</address></pre>",
        "<article><address>PHP/8.4.26 Apache/2.4.62</address></article>",
    ] {
        let server = Server::new(move |_| response("404 Not Found", "", body));
        let report = inspect(&server, &settings(), 1);
        assert!(report["version"].is_null(), "{body}: {report}");
        assert!(technology(&report, "Apache").is_none(), "{body}: {report}");
    }
}

#[test]
fn visible_error_footers_preserve_versions_across_inline_markup() {
    let server = Server::new(|_| {
        response(
            "404 Not Found",
            "",
            "<address>\
        <span>Apache/2.4.62</span> Server <b>PHP/8.4.26</b></address>",
        )
    });
    let report = inspect(&server, &settings(), 1);
    assert_eq!(report["version"]["major"], 8);
    assert_eq!(report["version"]["patch"], 26);
    assert_eq!(
        technology(&report, "Apache").unwrap()["versions"][0],
        "2.4.62"
    );
}

#[test]
fn a_robots_disclosure_promotes_an_already_planned_fallback() {
    let server = Server::new(|path| match path {
        "/" => response("200 OK", "", "application"),
        "/robots.txt" => response("200 OK", "", "Disallow: /version.php\n"),
        _ => response("404 Not Found", "", "missing"),
    });
    let mut options = settings();
    options.discover = true;
    options.deep = true;
    inspect(&server, &options, 3);
    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/robots.txt", "/version.php"]
    );
}

#[test]
fn discovery_does_not_refetch_a_queued_route_already_reached_by_redirect() {
    let server = Server::new(|path| match path {
        "/" => response("200 OK", "", "application"),
        "/alias" => response("302 Found", "Location: /info.php\r\n", ""),
        _ => response("200 OK", "", "diagnostic"),
    });
    let mut options = settings();
    options.discover = true;
    options.paths = vec!["alias".into(), "info.php".into()];
    let report = inspect(&server, &options, 8);
    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/alias", "/info.php"]
    );
    assert_eq!(
        report["analysis"]["diagnostics_completed"],
        report["analysis"]["diagnostics_requested"]
    );
}

#[test]
fn incomplete_bodies_keep_header_evidence_but_never_parse_partial_body_proofs() {
    let server = Server::new(|_| {
        "HTTP/1.1 200 OK\r\nConnection: close\r\n\
        X-PHP-Version: 8.4.26\r\nContent-Length: 9999\r\n\r\n\
        {\"php_version\":\"8.4.27\"}"
            .into()
    });
    let report = inspect(&server, &settings(), 1);
    assert_eq!(report["version"]["patch"], 26, "{report}");
    assert_eq!(report["observations"].as_array().unwrap().len(), 1);
    assert!(!report["analysis"]["coverage_complete"].as_bool().unwrap());
    assert!(!report["analysis"]["gaps"].as_array().unwrap().is_empty());
    assert!(
        report["version_candidates"]
            .as_array()
            .unwrap()
            .iter()
            .all(|c| c["version"]["patch"] == 26)
    );
}

#[test]
fn invalid_library_limits_are_rejected_before_network_without_panicking() {
    let server = Server::new(|_| response("200 OK", "", "OK"));
    for kind in 0..3 {
        let mut bounds = limits();
        match kind {
            0 => bounds.max_body = usize::MAX,
            1 => bounds.timeout = Duration::ZERO,
            _ => bounds.max_body = 0,
        }
        let result = std::panic::catch_unwind(|| scan_configured(&server.url, bounds, &settings()));
        assert!(result.is_ok(), "invalid limits must not panic");
        assert!(
            result.unwrap().is_err(),
            "invalid limits must fail preflight"
        );
    }
    assert!(server.paths.lock().unwrap().is_empty());
}

#[test]
fn a_zero_request_budget_returns_an_error_report_without_network_activity() {
    let server = Server::new(|_| response("200 OK", "", "OK"));
    let report = inspect(&server, &settings(), 0);
    assert_eq!(report["verdict"], "error");
    assert_eq!(report["requests_sent"], 0);
    assert!(!report["analysis"]["coverage_complete"].as_bool().unwrap());
    assert!(server.paths.lock().unwrap().is_empty());
}

#[test]
fn an_incomplete_diagnostic_body_still_exposes_conflicting_header_evidence() {
    let server = Server::new(|path| match path {
        "/" => response("200 OK", "X-PHP-Version: 8.4.27\r\n", "application"),
        "/info.php" => "HTTP/1.1 200 OK\r\nConnection: close\r\n\
            X-PHP-Version: 8.4.26\r\nContent-Length: 9999\r\n\r\n\
            {\"php_version\":\"8.5.12\"}"
            .into(),
        _ => response("404 Not Found", "", "missing"),
    });
    let mut options = settings();
    options.discover = true;
    options.paths = vec!["info.php".into()];
    let report = inspect(&server, &options, 4);
    assert_eq!(report["version_status"], "conflicting");
    assert!(report["version"].is_null());
    let candidates = report["version_candidates"].as_array().unwrap();
    assert_eq!(candidates.len(), 2);
    for patch in [26, 27] {
        assert!(
            candidates
                .iter()
                .any(|candidate| candidate["version"]["patch"] == patch)
        );
    }
    assert_eq!(report["observations"][1]["body_incomplete"], true);
    assert!(!report["analysis"]["coverage_complete"].as_bool().unwrap());
    assert!(!report["analysis"]["gaps"].as_array().unwrap().is_empty());
}

#[test]
fn article_examples_do_not_supply_generator_or_component_inventory() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "",
            "<article>\
        <meta name='generator' content='WordPress 6.8.1'>\
        <script src='/wp-content/plugins/example/main.js'></script>\
        <img src='/wp-content/themes/example/image.png'></article>",
        )
    });
    let report = inspect(&server, &settings(), 1);
    assert!(report["technologies"].as_array().unwrap().is_empty());
    assert!(report["version"].is_null());
    assert_eq!(report["runtime"]["status"], "unknown");
}

#[test]
fn redirect_fragments_do_not_consume_the_budget_for_a_distinct_diagnostic() {
    let server = Server::new(|path| match path {
        "/" => response("200 OK", "", "application"),
        "/alias" => response("302 Found", "Location: /info.php#runtime\r\n", ""),
        _ => response("200 OK", "", "diagnostic"),
    });
    let mut options = settings();
    options.discover = true;
    options.paths = vec!["alias".into(), "info.php".into(), "version.php".into()];
    let report = inspect(&server, &options, 4);
    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/alias", "/info.php", "/version.php"]
    );
    assert_eq!(report["requests_sent"], 4);
    assert_eq!(
        report["analysis"]["diagnostics_completed"],
        report["analysis"]["diagnostics_requested"]
    );
}

#[test]
fn distinct_diagnostic_query_values_keep_distinct_request_identities() {
    let server = Server::new(|_| response("200 OK", "", "application"));
    let mut options = settings();
    options.discover = true;
    options.paths = vec!["info.php?mode=1".into(), "info.php?mode=2".into()];
    let report = inspect(&server, &options, 3);
    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/info.php?mode=1", "/info.php?mode=2"]
    );
    assert_eq!(report["requests_sent"], 3);
    assert!(!report.to_string().contains("mode="));
    assert_eq!(
        report["analysis"]["diagnostics_completed"],
        report["analysis"]["diagnostics_requested"]
    );
}
